#include <bits/stdc++.h>
using namespace std;
template<typename T> inline void checkMin(T &a, T b) { if(b<a) a=b; }
template<typename T> inline void checkMax(T &a, T b) { if(a<b) a=b; }
#define X first
#define Y second
#define MP make_pair
#define PB push_back
#define SZ(c) int((c).size())
#define ALL(c) (c).begin(),(c).end()
#define REP(i,n) for (int i=0;i<int(n);++i)
typedef long long lint;
typedef vector<int> VI;
typedef pair<int, int> PII;

const int MOD = 1e9 + 7;

struct Matrix {
  static const int MAXN = 32;
  int N;
  int a[MAXN][MAXN];

  void init(int _N, int _V) {
    N = _N;
    fill(a[0], a[N], _V);
  }

  void multiply(const Matrix& b) {
    static Matrix temp, copyA, copyB;
    REP (i, N) REP (j, N)
      copyA.a[i][j] = a[i][j], copyB.a[i][j] = b.a[i][j];
    REP (i, N) REP (j, N) {
      lint t = 0;
      REP (k, N) t += lint(copyA.a[i][k]) * copyB.a[k][j] % MOD;
      a[i][j] = t % MOD;
    }
  }
} A[64][32], prefix[64][32], suffix[64][32];

lint n;
int k;

void precompute(int idx) {
  prefix[idx][1] = A[idx][0];
  for (int j=2; j<=k; ++j) {
    prefix[idx][j] = prefix[idx][j-1];
    prefix[idx][j].multiply(A[idx][j-1]);
  }
  suffix[idx][k-1] = A[idx][k-1];
  for (int j=k-2; j>=0; --j) {
    suffix[idx][j] = A[idx][j];
    suffix[idx][j].multiply(suffix[idx][j+1]);
  }
}

int sumDigits(lint num) {
  int s=0;
  for (; num; num/=k) {
    (s += num % k) %= k;
  }
  return s;
}

Matrix getResult(lint num, int m) {
  if (num < k) {
    Matrix res = A[m][0];
    for (int i=1; i<num; ++i) {
      res.multiply(A[m][i]);
    }
    return res;
  }
  Matrix res = getResult(num / k, m+1);
  int x = sumDigits(num / k);
  for (int i=0; i<num%k; ++i) {
    res.multiply(A[m][(x + i) % k]);
  }
  return res;
}

int main() {
  cin >> n >> k;
  REP (i, k) {
    A[0][i].init(k+1, 0);
    REP (j, k+1) {
      A[0][i].a[j][j] = 1;
      A[0][i].a[j][i] = 1;
    }
  }
  for (int m=1; pow(k,m)-1000<=n; ++m) {
    precompute(m-1);
    REP (x, k) {
      A[m][x] = suffix[m-1][x];
      if (x > 0) {
        A[m][x].multiply(prefix[m-1][x]);
      }
    }
  }
  Matrix answerMat = getResult(n, 0);
  int totalSum=0;
  REP (i, k+1) {
    (totalSum += answerMat.a[k][i]) %= MOD;
  }
  cout << totalSum << endl;
  return 0;
}
